questionvariables.text:
vB: rand([1,2,3,4,5]);
ceAL: [9,1,1,1,3];
ceBL: [16,2,1,4,1];
holdAL: [0,1,2,3,2];
holdBL: [4,1,2,3,2];
ceA: ceAL[vB];
ceB: ceBL[vB];
holdA: holdAL[vB];
holdB: holdBL[vB];
/* A second pair at which the conjecture holds, in surd or logarithm form: used by the question tests. */
altAL: [0, log(3)/log(2), 1+sqrt(2), sqrt(8), sqrt(2)];
altBL: [sqrt(2), log(3/2)/log(2), 1+1/sqrt(2), 2*sqrt(2), sqrt(2)];
altA: altAL[vB];
altB: altBL[vB];
lhsB(a,b) := if vB = 1 then sqrt(a+b) else if vB = 2 then 2^(a+b) else if vB = 3 then log(a+b) else if vB = 4 then sqrt(a*b) else (a-b)^2;
rhsB(a,b) := if vB = 1 then sqrt(a)+sqrt(b) else if vB = 2 then 2^a+2^b else if vB = 3 then log(a)+log(b) else if vB = 4 then (a+b)/2 else a^2-b^2;
domB(a,b) := if vB = 1 then (is(a >= 0) and is(b >= 0)) else (is(a > 0) and is(b > 0));
/* scB: the size of the terms in the conjecture, the scale for the numerical comparison in the PRT. Variant 1 holds only when a or b is 0, which cannot be told numerically from a very small value, so it has no numerical comparison (scale 0). */
scB(a,b) := if vB = 1 then 0 else if vB = 2 then 2^a+2^b else if vB = 3 then 1+abs(log(a))+abs(log(b)) else if vB = 4 then (a+b)/2 else a^2+b^2;
condB: if vB = 1 then "real numbers \\(a\\) and \\(b\\) with \\(a \\ge 0\\) and \\(b \\ge 0\\)" else "positive real numbers \\(a\\) and \\(b\\)";
condShortB: if vB = 1 then "\\(a \\ge 0\\) and \\(b \\ge 0\\)" else "positive \\(a\\) and \\(b\\)";
eqB: ["\\(\\sqrt{a+b}=\\sqrt{a}+\\sqrt{b}\\)", "\\(2^{a+b}=2^a+2^b\\)", "\\(\\ln(a+b)=\\ln a+\\ln b\\)", "\\(\\sqrt{ab}=\\dfrac{a+b}{2}\\)", "\\((a-b)^2=a^2-b^2\\)"][vB];
wordsB: ["sqrt(a+b) = sqrt(a) + sqrt(b), a, b >= 0", "2^(a+b) = 2^a + 2^b, a, b > 0", "ln(a+b) = ln(a) + ln(b), a, b > 0", "sqrt(ab) = (a+b)/2, a, b > 0", "(a-b)^2 = a^2 - b^2, a, b > 0"][vB];
whenB: ["\\(a=0\\) or \\(b=0\\)", "\\((2^a-1)(2^b-1)=1\\)", "\\(a+b=ab\\)", "\\(a=b\\)", "\\(a=b\\)"][vB];
ruleB: ["The correct relationship is the inequality \\(\\sqrt{a+b}\\le\\sqrt{a}+\\sqrt{b}\\): squaring the right-hand side gives \\(a+b+2\\sqrt{ab}\\), not \\(a+b\\).", "The correct law of indices is \\(2^{a+b}=2^a\\times 2^b\\): adding powers corresponds to multiplying, not adding.", "The correct law of logarithms is \\(\\ln(ab)=\\ln a+\\ln b\\): the logarithm of a product, not of a sum, splits into a sum.", "The correct relationship is the inequality \\(\\sqrt{ab}\\le\\dfrac{a+b}{2}\\) (the geometric mean is at most the arithmetic mean), with equality only when \\(a=b\\).", "The correct expansion is \\((a-b)^2=a^2-2ab+b^2\\); it is \\(a^2-b^2\\) that factorises as \\((a-b)(a+b)\\)."][vB];
ceLv: ev(lhsB(ceA, ceB), simp);
ceRv: ev(rhsB(ceA, ceB), simp);
hLv: ev(lhsB(holdA, holdB), simp);
hRv: ev(rhsB(holdA, holdB), simp);
s_assert(is(ev(radcan(ceLv - ceRv), simp) = 0), false);
s_assert(is(ev(radcan(hLv - hRv), simp) = 0), true);
/* validate_real: the numerical input accepts i, inf, sets, lists, booleans and equations; only a real number may reach the PRT. Same validator as Ch02_P01_Checks_are_not_a_proof. */
validate_real(ex) := block([sv, fv], sv: ev(ex, simp), fv: errcatch(ev(bfloat(sv), simp)), if ratnump(sv) then "" else if is(fv = []) then "Enter a single real number, for example 3, -1/2 or sqrt(2)." else if bfloatp(first(fv)) then "" else "Enter a single real number, for example 3, -1/2 or sqrt(2).");
/* nearzero: a numerical fallback for entries that do not simplify exactly, such as sin(1)^2+cos(1)^2 for 1. True when the size of z is less than 10^(-12) times the size of sc: z is 0 to within rounding error, on the scale sc. */
nearzero(z, sc) := block([fz, fs], fz: errcatch(ev(float(z), numer, simp)), fs: errcatch(ev(float(sc), numer, simp)), if is(fz = []) or is(fs = []) then return(false), fz: first(fz), fs: first(fs), if floatnump(fz) and floatnump(fs) then is(abs(fz) < 10^(-12)*abs(fs)) else false);

feedbackvariables.text:
sa: ev(ans1, simp);
sb: ev(ans2, simp);
inD: domB(sa, sb);
Lv: if inD then ev(lhsB(sa, sb), simp) else 0;
Rv: if inD then ev(rhsB(sa, sb), simp) else 0;
/* Exact test first. A pair typed in a form that does not simplify exactly, such as sin(1)^2+cos(1)^2 for 1, is then compared numerically, on the scale scB; rational pairs are only compared exactly. */
nearB: if inD then (not (ratnump(sa) and ratnump(sb)) and nearzero(Lv - Rv, scB(sa, sb))) else false;
holdsB: if inD then (is(ev(radcan(Lv - Rv), simp) = 0) or nearB) else false;
